def calculate(s):
    res, num, sign = 0, 0, 1
    stack = []                         # (res before '(', sign before '(')
    for c in s:
        if c.isdigit():
            num = num * 10 + int(c)
        elif c in '+-':
            res += sign * num
            num, sign = 0, (1 if c == '+' else -1)
        elif c == '(':
            stack.append(res)
            stack.append(sign)
            res, sign = 0, 1
        elif c == ')':
            res += sign * num
            num = 0
            res *= stack.pop()         # sign before the paren
            res += stack.pop()         # result before the paren
    return res + sign * num

