def calculate(s):
    def parse(i):                      # evaluate from s[i] up to the matching ')'
        res, num, sign = 0, 0, 1
        while i < len(s):
            c = s[i]
            if c.isdigit():
                num = num * 10 + int(c)
            elif c in '+-':
                res += sign * num
                num, sign = 0, (1 if c == '+' else -1)
            elif c == '(':
                num, i = parse(i + 1)  # the whole group acts as one number
            elif c == ')':
                return res + sign * num, i
            i += 1
        return res + sign * num, i

    return parse(0)[0]

P18-evaluate-reverse-polish-notation:
def eval_rpn(tokens):
    stack = []
    for t in tokens:
        if t in {'+', '-', '*', '/'}:
            b, a = stack.pop(), stack.pop()    # right operand pops first
            if t == '+':
                stack.append(a + b)
            elif t == '-':
                stack.append(a - b)
            elif t == '*':
                stack.append(a * b)
            else:
                stack.append(int(a / b))       # truncate toward zero
        else:
            stack.append(int(t))
    return stack[0]

